import math


def _key(row):
    if not hasattr(row, "__getitem__"):
        raise TypeError("rows must be mappings")
    try:
        device = row["device"]
        sequence = row["sequence"]
    except (KeyError, TypeError) as exc:
        raise ValueError("row is missing a key field") from exc
    if not isinstance(device, str):
        raise TypeError("device must be a string")
    if not device:
        raise ValueError("device must not be empty")
    if not isinstance(sequence, int) or isinstance(sequence, bool):
        raise TypeError("sequence must be an integer")
    if sequence < 0:
        raise ValueError("sequence must be non-negative")
    return device, sequence


def _number(value, label):
    if not isinstance(value, (int, float)) or isinstance(value, bool):
        raise TypeError(f"{label} must be numeric")
    if not math.isfinite(value):
        raise ValueError(f"{label} must be finite")
    return value


def combine_measurements(primary, corrections):
    base = {}
    for row in primary:
        key = _key(row)
        if key in base:
            raise ValueError("duplicate primary key")
        try:
            value = _number(row["value"], "value")
            tags = row["tags"]
        except KeyError as exc:
            raise ValueError("primary row is missing a field") from exc
        if not isinstance(tags, list):
            raise TypeError("tags must be a list")
        if any(not isinstance(tag, str) for tag in tags):
            raise TypeError("tags must contain strings")
        base[key] = (value, list(tags))

    offsets = {}
    for row in corrections:
        key = _key(row)
        if key in offsets:
            raise ValueError("duplicate correction key")
        try:
            offsets[key] = _number(row["offset"], "offset")
        except KeyError as exc:
            raise ValueError("correction row is missing offset") from exc

    result = []
    for device, sequence in sorted(base, key=lambda item: (item[1], item[0])):
        value, tags = base[(device, sequence)]
        result.append({
            "device": device,
            "sequence": sequence,
            "adjusted": value + offsets.get((device, sequence), 0),
            "tags": list(tags),
        })
    return result
